27	
28	  function showFallback() {
29	    if (done) return;
30	    done = true;
31	    const mount = document.querySelector(MOUNT_SEL);
32	    const fb = document.getElementById(FALLBACK_ID);
33	    if (mount) mount.setAttribute('hidden', '');
