72	      if (mount.querySelector(SUCCESS_SEL)) {
73	        markSuccess();
74	        mo.disconnect();
75	      }
76	    });
77	    mo.observe(mount, { childList: true, subtree: true });
78	
79	    // Direct listeners on the island element if already in DOM
80	    const island = mount.querySelector('astro-island');
81	    if (island) {
82	      island.addEventListener('astro:hydrate', markSuccess, { once: true });
83	      island.addEventListener('astro:hydration-error', showFallback, { once: true });
84	    }
85	
86	    // If content already present (race or fast path)
87	    if (mount.querySelector(SUCCESS_SEL)) {
88	      markSuccess();
89	    }
90	  }
