93	  const watchdog = setTimeout(() => {
94	    if (done) return;
95	    const mount = document.querySelector(MOUNT_SEL);
96	    if (mount && mount.querySelector(SUCCESS_SEL)) {
97	      markSuccess();
98	      return;
99	    }
